from __future__ import annotations

import uuid
from dataclasses import dataclass
from typing import Any

try:
    from domains.bo_mcp.client import BoMcpClient  # type: ignore
except ImportError:  # pragma: no cover - workspace bootstrap path
    BoMcpClient = None  # type: ignore


@dataclass
class NextAction:
    action: str
    reason: str


class BoMcpCompatClient:
    def __init__(self, inner: Any) -> None:
        self._inner = inner

    @classmethod
    def from_env(cls) -> "BoMcpCompatClient":
        if BoMcpClient is None:
            raise RuntimeError(
                "BoMcpClient import failed. Run from this workspace with "
                "'uv run --active python run_butanol_dihedral_campaign.py' so the "
                "repository modules are importable."
            )
        return cls(BoMcpClient.from_env())

    def create_campaign(self, intake: dict[str, Any]) -> dict[str, Any]:
        self._inner.validate_intake(intake)
        return self._inner.create_campaign(intake, idempotency_key=str(uuid.uuid4()))

    def get_campaign(self, campaign_id: str) -> dict[str, Any]:
        return self._inner.get_campaign(campaign_id)

    def lifecycle(self, campaign_id: str, action: str) -> dict[str, Any]:
        return self._inner.lifecycle(campaign_id, action=action)

    def generate_suggestion(self, campaign_id: str) -> dict[str, Any]:
        payload = self._inner.generate_suggestions(campaign_id, batch_size=1)
        suggestions = payload["suggestions"]
        if len(suggestions) != 1:
            raise RuntimeError(f"Expected one suggestion, received {len(suggestions)}")
        return suggestions[0]

    def submit_result(
        self,
        campaign_id: str,
        *,
        suggestion_id: str,
        parameter_values: dict[str, Any],
        objective_values: dict[str, float],
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        return self._inner.submit_results(
            campaign_id,
            results=[
                {
                    "suggestion_id": suggestion_id,
                    "parameter_values": parameter_values,
                    "objective_values": objective_values,
                    "metadata": metadata,
                }
            ],
            idempotency_key=f"submit-{suggestion_id}",
        )

    def result_count(self, campaign_id: str) -> int:
        return len(self._inner.get_results(campaign_id))

    def pending_suggestions(self, campaign_id: str) -> list[dict[str, Any]]:
        return list(self._inner.query_suggestions(campaign_id, status_filter="pending"))

    def next_action(self, campaign_id: str) -> NextAction:
        payload = self._inner.next_action(campaign_id)
        return NextAction(
            action=str(payload.get("action", "stop")),
            reason=str(payload.get("reason", "No reason provided.")),
        )

