def _mock_energy(parameter_values: dict[str, float]) -> float:
    angles = [math.radians(float(value)) for value in parameter_values.values()]
    return -231.0 + sum(0.004 * (1.0 - math.cos(angle)) for angle in angles) + 0.0015 * (
        1.0 - math.cos(angles[0] - angles[1])
    )



def _scientific_batch_request(
    *,
    run_id: str,
    xyz_text: str,
    molecule_timeout_seconds: float,
) -> dict[str, Any]:
    return {
        "schema_version": 3,
        "batch_id": run_id,
        "molecules": [
            {
                "schema_version": 3,
                "run_id": run_id,
                "summarised_user_query": (
                    "1-butanol single-point energy only; optimize the three dihedrals "
                    "including H-O-C-C; no geometry optimization, no frequencies, "
                    "no molecular analysis."
                ),
                "identifier": {
                    "type": "xyz",
                    "value": xyz_text,
                    "charge": 0,
                    "spin_multiplicity": 1,
                    "basis_set": "def2-SVP",
                    "restricted": True,
                    "xc_functional": "PBE-D4",
                    "accelerator_policy": "auto",
                },
                "workflow": {"stop_after": "SinglePointCalculation"},
            }
        ],
        "max_parallel_molecules": 1,
        "molecule_timeout_seconds": molecule_timeout_seconds,
        "fail_fast": True,
    }



def _normalize_payload(payload: Any) -> dict[str, Any]:
    if hasattr(payload, "model_dump"):
        return payload.model_dump(mode="json")
    if isinstance(payload, dict):
        return payload
    raise TypeError(f"Unsupported payload type: {type(payload)!r}")



def evaluate_candidate(
    *,
    parameter_values: dict[str, float],
    evaluator: str,
    artifact_dir: Path,
    attempt_index: int,
    molecule_timeout_seconds: float,
) -> dict[str, Any]:
    started_at = time.time()
    artifact_dir.mkdir(parents=True, exist_ok=True)
    xyz_text = candidate_to_xyz(parameter_values)
    xyz_path = artifact_dir / f"attempt_{attempt_index:03d}.xyz"
    xyz_path.write_text(xyz_text, encoding="utf-8")

    if evaluator == "mock":
        energy = _mock_energy(parameter_values)
        return {
            "objective_values": {OBJECTIVE_NAME: energy},
            "metadata": {
                "notes": f"Mock evaluator for {METHOD_BASIS_LABEL} plumbing smoke test.",
                "conditions": {
                    "evaluator": "mock",
                    "xyz_file": str(xyz_path),
                    "elapsed_s": round(time.time() - started_at, 3),
                },
            },
            "scientific_payload": {"status": "mock", "total_energy": energy},
            "xyz_path": str(xyz_path),
        }

    if PySCFRunnerClient is None:
        raise RuntimeError(
            "PySCFRunnerClient import failed. Run with 'uv run --active python "
            "run_butanol_dihedral_campaign.py' so the repository modules are on sys.path, "
            "or use --evaluator mock for the bounded smoke test."
        )

    run_id = f"butanol-dihedral-attempt-{attempt_index:03d}"
    batch_request = _scientific_batch_request(
        run_id=run_id,
        xyz_text=xyz_text,
        molecule_timeout_seconds=molecule_timeout_seconds,
    )
    client = PySCFRunnerClient.from_env()
    try:
        raw_result = client.evaluate(
            request=batch_request,
            timeout_seconds=int(molecule_timeout_seconds),
        )
    except ValueError as exc:
        if "timeout exceeds deployment profile limit" not in str(exc):
            raise
        raw_result = client.evaluate(request=batch_request, timeout_seconds=None)
    payload = _normalize_payload(raw_result)
    molecule_payload = payload["molecules"][0]["result"]
    if molecule_payload.get("status") != "ok":
        raise RuntimeError(molecule_payload.get("error") or str(molecule_payload))
    total_energy = molecule_payload.get("total_energy")
    if total_energy is None:
        raise RuntimeError(f"Scientific result missing total_energy: {molecule_payload}")
    result_path = artifact_dir / f"attempt_{attempt_index:03d}_scientific.json"
    result_path.write_text(json.dumps(payload, sort_keys=True, indent=2), encoding="utf-8")
    return {
        "objective_values": {OBJECTIVE_NAME: float(total_energy)},
        "metadata": {
            "notes": f"Single-point {METHOD_BASIS_LABEL}.",
            "conditions": {
                "evaluator": "scientific",
                "xyz_file": str(xyz_path),
                "scientific_result_file": str(result_path),
                "elapsed_s": round(time.time() - started_at, 3),
            },
        },
        "scientific_payload": molecule_payload,
        "xyz_path": str(xyz_path),
    }

