from dataclasses import dataclass
from typing import Any, Mapping

from .constants import EVALUATION_BUDGET, OBJECTIVE_NAME, TORSION_SPECS


@dataclass(frozen=True)
class AttemptState:
    attempted: int
    succeeded: int
    failed: int


def extract_objective_value(batch_result: Mapping[str, Any]) -> float:
    molecules = batch_result.get("molecules")
    if not isinstance(molecules, list) or len(molecules) != 1:
        raise RuntimeError("Expected exactly one molecule in the PySCF batch result")
    molecule_result = molecules[0].get("result")
    if not isinstance(molecule_result, Mapping):
        raise RuntimeError("PySCF batch result is missing molecule result data")
    completed_nodes = molecule_result.get("completed_nodes")
    if completed_nodes != ["SinglePointCalculation"]:
        raise RuntimeError(
            f"Expected single-point-only execution, got completed_nodes={completed_nodes!r}"
        )
    energy = molecule_result.get("total_energy")
    if not isinstance(energy, (int, float)):
        raise RuntimeError("PySCF batch result does not contain a finite total energy")
    return float(energy)


def summarize_attempt_state(client: Any, campaign_id: str) -> tuple[AttemptState, list[dict[str, Any]], list[dict[str, Any]]]:
    results = list(client.get_results(campaign_id))
    rejected = list(client.query_suggestions(campaign_id, status_filter="rejected", limit=EVALUATION_BUDGET + 20))
    state = AttemptState(
        attempted=len(results) + len(rejected),
        succeeded=len(results),
        failed=len(rejected),
    )
    return state, results, rejected


def format_parameter_values(parameter_values: Mapping[str, Any]) -> str:
    ordered = [
        f"{spec['name']}={float(parameter_values[spec['name']]):.3f}"
        for spec in TORSION_SPECS
    ]
    return ", ".join(ordered)


def objective_payload(value: float) -> dict[str, float]:
    return {OBJECTIVE_NAME: float(value)}
